(195,1,'2024-11-23 15:03:31','2024-11-23 15:03:31','<!-- wp:paragraph -->\n<p>ماليزيا – توقيع شراكة استراتيجية بين معهد الوافي الإسلامي والجامعة الوطنية الماليزية لتطوير مدارس دولية مبتكرة</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>وقّع معهد الوافي الإسلامي الداخلي، التابع لمؤسسة السديس في إندونيسيا، اتفاقية شراكة استراتيجية مع الجامعة الوطنية الماليزية (UKM) في 18 نوفمبر 2024. عُقد حفل التوقيع في قاعة المجلس بالطابق الخامس من مبنى إدارة الجامعة الوطنية الماليزية، في إطار الجهود الرامية إلى تطوير مفهوم مدرسة دولية مبتكرة تعتمد على القيم الإسلامية.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\"><strong>شراكة متعددة الأطراف</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>تضمّنت هذه الشراكة تعاونًا بين:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"ordered\":true} -->\n<ol class=\"wp-block-list\"><!-- wp:list-item -->\n<li>الجامعة الوطنية الماليزية (UKM).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>مؤسسة السديس.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>مجموعة التعليم الدولية لمنطقة خليج جوانجدونج-هونج كونج-ماكاو (GBI).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>شركة تطوير المشاريع التعليمية والتدريبية (M Circle Sdn. Bhd).</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\"><strong>تطوير تعليم بمعايير دولية</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>شهد الحفل حضور شخصيات بارزة من الطرفين، منهم:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>الأستاذ الدكتور <strong>علي شامان حسن</strong> (مؤسس معهد الوافي الإسلامي الدولي).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>الأستاذ الدكتور <strong>مارالله مرزوق</strong> (رئيس مؤسسة السديس، إندونيسيا).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>الأستاذ الدكتور <strong>محمد إحوان توريمان</strong> (رئيس الجامعة الوطنية الماليزية).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>الأستاذ الدكتور <strong>محمد حسين</strong> (مدير قسم التطوير بالجامعة الوطنية الماليزية).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>السيد <strong>داتوك أحمد شاليمين أحمد شافي</strong> (عضو مجلس إدارة UKM).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>الأستاذ الدكتور <strong>عبد الحليم عبد الغفور</strong> (نائب الرئيس للشؤون الأكاديمية والدولية في UKM).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>الأستاذة الدكتورة <strong>إسمنيزان إسماعيل</strong> (مديرة المركز الوطني الماليزي لرعاية المتفوقين والموهوبين).</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>بدأ الحفل بترحيب الضيوف وعرض فيديو تعريفي عن الجامعة الوطنية الماليزية، تلاه خطاب من الأستاذ الدكتور محمد إحوان توريمان. اختُتم الحدث بتوقيع اتفاقية الشراكة، أعقبته جلسة تصوير وتبادل الهدايا التذكارية.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\"><strong>رؤية مشتركة لمستقبل التعليم</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>تركز الشراكة على:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>تطوير منهج دولي يدمج بين القيم الإسلامية والأساليب التعليمية الحديثة.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>تدريب المعلمين.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>تبادل الطلاب.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>تحسين المرافق الأكاديمية.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>وأشار الأستاذ الدكتور علي شامان حسن إلى أن هذه الشراكة تمثل خطوة جوهرية نحو تعزيز دور معهد الوافي في تخريج جيل يتميز أكاديميًا وأخلاقيًا، ويحمل رؤية عالمية. وأضاف: <em>\"نؤمن بأن التعليم عالي الجودة هو المفتاح لبناء حضارة أفضل\".</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>وأكد أن خطة إنشاء المدرسة الدولية بدأت رسميًا، وستُنفذ بالكامل بحلول العام الدراسي الجديد في يوليو 2025.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\"><strong>تطلعات نحو التعليم الدولي</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>من خلال هذه الشراكة، تسعى الوافي والجامعة الوطنية الماليزية إلى تقديم مساهمة كبيرة في تطوير التعليم الدولي، خاصة في إندونيسيا، بما يعزز بناء مجتمع معرفي قوي.</p>\n<!-- /wp:paragraph -->','معهد الوافي الإسلامي يتعاون مع الجامعة الوطنية الماليزية لتطوير المدارس الدولية','','publish','open','open','','%d8%b9%d9%87%d8%af-%d8%a7%d9%84%d9%88%d8%a7%d9%81%d9%8a-%d8%a7%d9%84%d8%a5%d8%b3%d9%84%d8%a7%d9%85%d9%8a-%d9%8a%d8%aa%d8%b9%d8%a7%d9%88%d9%86-%d9%85%d8%b9-%d8%a7%d9%84%d8%ac%d8%a7%d9%85%d8%b9%d8%a9','','','2024-11-23 15:06:55','2024-11-23 15:06:55','',0,'https://arabic.al-wafi.sch.id/news/?p=195',0,'post','',0),
(196,1,'2024-11-23 15:03:10','2024-11-23 15:03:10','','image','','inherit','open','closed','','image-70','','','2024-11-23 15:03:10','2024-11-23 15:03:10','',195,'https://arabic.al-wafi.sch.id/news/wp-content/uploads/2024/11/image.png',0,'attachment','image/png',0),
(197,1,'2024-11-23 15:03:31','2024-11-23 15:03:31','<!-- wp:paragraph -->\n<p>ماليزيا – توقيع شراكة استراتيجية بين معهد الوافي الإسلامي والجامعة الوطنية الماليزية لتطوير مدارس دولية مبتكرة</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>وقّع معهد الوافي الإسلامي الداخلي، التابع لمؤسسة السديس في إندونيسيا، اتفاقية شراكة استراتيجية مع الجامعة الوطنية الماليزية (UKM) في 18 نوفمبر 2024. عُقد حفل التوقيع في قاعة المجلس بالطابق الخامس من مبنى إدارة الجامعة الوطنية الماليزية، في إطار الجهود الرامية إلى تطوير مفهوم مدرسة دولية مبتكرة تعتمد على القيم الإسلامية.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\"><strong>شراكة متعددة الأطراف</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>تضمّنت هذه الشراكة تعاونًا بين:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"ordered\":true} -->\n<ol class=\"wp-block-list\"><!-- wp:list-item -->\n<li>الجامعة الوطنية الماليزية (UKM).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>مؤسسة السديس.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>مجموعة التعليم الدولية لمنطقة خليج جوانجدونج-هونج كونج-ماكاو (GBI).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>شركة تطوير المشاريع التعليمية والتدريبية (M Circle Sdn. Bhd).</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\"><strong>تطوير تعليم بمعايير دولية</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>شهد الحفل حضور شخصيات بارزة من الطرفين، منهم:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>الأستاذ الدكتور <strong>علي شامان حسن</strong> (مؤسس معهد الوافي الإسلامي الدولي).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>الأستاذ الدكتور <strong>مارالله مرزوق</strong> (رئيس مؤسسة السديس، إندونيسيا).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>الأستاذ الدكتور <strong>محمد إحوان توريمان</strong> (رئيس الجامعة الوطنية الماليزية).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>الأستاذ الدكتور <strong>محمد حسين</strong> (مدير قسم التطوير بالجامعة الوطنية الماليزية).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>السيد <strong>داتوك أحمد شاليمين أحمد شافي</strong> (عضو مجلس إدارة UKM).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>الأستاذ الدكتور <strong>عبد الحليم عبد الغفور</strong> (نائب الرئيس للشؤون الأكاديمية والدولية في UKM).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>الأستاذة الدكتورة <strong>إسمنيزان إسماعيل</strong> (مديرة المركز الوطني الماليزي لرعاية المتفوقين والموهوبين).</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>بدأ الحفل بترحيب الضيوف وعرض فيديو تعريفي عن الجامعة الوطنية الماليزية، تلاه خطاب من الأستاذ الدكتور محمد إحوان توريمان. اختُتم الحدث بتوقيع اتفاقية الشراكة، أعقبته جلسة تصوير وتبادل الهدايا التذكارية.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\"><strong>رؤية مشتركة لمستقبل التعليم</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>تركز الشراكة على:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>تطوير منهج دولي يدمج بين القيم الإسلامية والأساليب التعليمية الحديثة.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>تدريب المعلمين.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>تبادل الطلاب.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>تحسين المرافق الأكاديمية.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>وأشار الأستاذ الدكتور علي شامان حسن إلى أن هذه الشراكة تمثل خطوة جوهرية نحو تعزيز دور معهد الوافي في تخريج جيل يتميز أكاديميًا وأخلاقيًا، ويحمل رؤية عالمية. وأضاف: <em>\"نؤمن بأن التعليم عالي الجودة هو المفتاح لبناء حضارة أفضل\".</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>وأكد أن خطة إنشاء المدرسة الدولية بدأت رسميًا، وستُنفذ بالكامل بحلول العام الدراسي الجديد في يوليو 2025.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\"><strong>تطلعات نحو التعليم الدولي</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>من خلال هذه الشراكة، تسعى الوافي والجامعة الوطنية الماليزية إلى تقديم مساهمة كبيرة في تطوير التعليم الدولي، خاصة في إندونيسيا، بما يعزز بناء مجتمع معرفي قوي.</p>\n<!-- /wp:paragraph -->','عهد الوافي الإسلامي يتعاون مع الجامعة الوطنية الماليزية لتطوير المدارس الدولية','','inherit','closed','closed','','195-revision-v1','','','2024-11-23 15:03:31','2024-11-23 15:03:31','',195,'https://arabic.al-wafi.sch.id/news/?p=197',0,'revision','',0),
